import{z}from"zod";import fs from"node:fs";import path from"node:path";import{logger}from"../libraries/logger/_logger.js";import{constants}from"../utils/constants/_constants.js";import{getEntireRecitersService}from"../services/reciter.services.js";const dependencies=async(req,response,next)=>{if(!constants.META_AVAILABLE_LANGUAGE.length){constants.META_AVAILABLE_LANGUAGE=fs.readdirSync(path.resolve("src","db","_translation","lang"))}if(!constants.META_RECITER_LIST.length){const getEntireReciters=await getEntireRecitersService();constants.META_RECITER_LIST=getEntireReciters.map(value=>value.id)}const dependenciesExtra={logger,constants,validator:z};req.ext=dependenciesExtra;next()};export{dependencies};